def solve():
    precipitation = step_198(
        Ksp_AB=Ksp_AgCl,
        Ksp2=Ksp_AgI,
        concentration_1=c_Cl,
        concentration_2=c_I
    )["precipitation"]

    if precipitation == "ion 1 precipitates first":
        first_concentration = c_Cl
        second_concentration = c_I
        first_ksp = Ksp_AgCl
        second_ksp = Ksp_AgI
    else:
        first_concentration = c_I
        second_concentration = c_Cl
        first_ksp = Ksp_AgI
        second_ksp = Ksp_AgCl

    equivalence_volume = V_initial * first_concentration / c_Ag
    q = second_ksp / second_concentration
    peak_volume = V_initial * (math.sqrt((c_Ag + first_concentration) / q) - 1)

    def mismatch(volume_added):
        total_volume = V_initial + volume_added
        cation_diluted = c_Ag * volume_added / total_volume
        anion_diluted = first_concentration * V_initial / total_volume
        signed_excess = cation_diluted - anion_diluted

        if not math.isclose(cation_diluted, anion_diluted, rel_tol=1e-6):
            residual = step_371(
                solubility_product=first_ksp,
                cation_concentration=c_Ag,
                volume_1=volume_added,
                anion_concentration=first_concentration,
                volume_2=V_initial
            )["residual_concentration"]
            signed_excess = first_ksp / residual
            if cation_diluted < anion_diluted:
                signed_excess = -signed_excess

        second_threshold_ag = second_ksp / (
            second_concentration * V_initial / total_volume
        )
        return signed_excess - second_threshold_ag

    if peak_volume <= equivalence_volume:
        return {"cannot": "The second precipitate does not begin to form after the first reaches equivalence for these values."}

    peak_mismatch = mismatch(peak_volume)
    if peak_mismatch < 0:
        return {"cannot": "The silver concentration is insufficient for the second precipitate to begin forming for these values."}
    if peak_mismatch == 0:
        return peak_volume

    return solve_for(mismatch, equivalence_volume, peak_volume)

